{"content":"/*
 * nullvec.c: compute the eigenvector (null vector of A - lambda I) for an
 * approximate/eigenvalue lambda of a real square matrix A.
 *
 * Entry: nullvec(A, n, lam_re, lam_im, out_re, out_im)
 *   A:     n*n real doubles (row-major)
 *   n:     matrix size (1..10)
 *   lam:   eigenvalue (complex)
 *   out_re, out_im: output vector, complex, normalized (n doubles each)
 * Returns int info: 0 on success, 1 on failure.
 */

#include <math.h>
#include <stdlib.h>
#include <string.h>
#include <complex.h>

#define MAXN 10

typedef double complex cplx;

static double cabs2(cplx z) {
    return creal(z)*creal(z) + cimag(z)*cimag(z);
}

int nullvec(const double *A, int n, double lam_re, double lam_im,
            double *out_re, double *out_im) {
    cplx B[MAXN][MAXN];
    int pivcol[MAXN];
    int npiv = 0;
    int freecol = -1;
    int i, j, row, col;

    if (n <= 0 || n > MAXN) return 1;

    /* build B = A - lambda I */
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            B[i][j] = A[i*n + j];
        }
        B[i][i] -= (lam_re + lam_im*I);
    }

    row = 0;
    col = 0;
    while (row < n && col < n) {
        /* find best pivot in column col from rows row..n-1 */
        int best = -1;
        double bestabs = 1e-300;
        for (i = row; i < n; i++) {
            double m2 = cabs2(B[i][col]);
            if (m2 > bestabs) {
                best = i;
                bestabs = m2;
            }
        }
        if (best < 0) {
            /* column col is linearly dependent -> free column */
            if (freecol < 0) freecol = col;
            col++;
            continue;
        }
        /* swap rows row and best */
        if (best != row) {
            for (j = 0; j < n; j++) {
                cplx tmp = B[row][j];
                B[row][j] = B[best][j];
                B[best][j] = tmp;
            }
        }
        pivcol[npiv++] = col;
        /* eliminate rows below */
        for (i = row + 1; i < n; i++) {
            cplx f = B[i][col] / B[row][col];
            for (j = col; j < n; j++) {
                B[i][j] -= f * B[row][j];
            }
        }
        row++;
        col++;
    }

    if (npiv != n - 1 || freecol < 0) {
        /* rank deficiency not exactly 1; give up (caller falls back) */
        return 1;
    }

    {
        cplx v[MAXN];
        double norm = 0.0, inv;

        memset(v, 0, sizeof(v));
        v[freecol] = 1.0;

        /* back substitution, bottom pivot row to top */
        for (i = npiv - 1; i >= 0; i--) {
            cplx s = 0.0;
            /* free column contribution */
            s = B[i][freecol] * v[freecol];
            /* later pivot columns */
            for (j = i + 1; j < npiv; j++) {
                s += B[i][pivcol[j]] * v[pivcol[j]];
            }
            v[pivcol[i]] = -s / B[i][pivcol[i]];
        }

        for (i = 0; i < n; i++) {
            norm += cabs2(v[i]);
        }
        if (norm == 0.0) return 1;
        inv = 1.0 / sqrt(norm);
        for (i = 0; i < n; i++) {
            out_re[i] = creal(v[i]) * inv;
            out_im[i] = cimag(v[i]) * inv;
        }
        return 0;
    }
}
